public int findLargestSubstring(List<String> strings) {
    int maxLength = 0;

    for (String str : strings) {
        for (String sub : generateSubstrings(str)) {
            if (anyStringContains(sub, strings)) {
                maxLength = Math.max(maxLength, sub.length());
            }
        }
    }

    return maxLength;
}

private List<String> generateSubstrings(String str) {
    List<String> substrings = new ArrayList<>();
    for (int i = 0; i < str.length(); i++) {
        for (int j = i + 1; j <= str.length(); j++) {
            substrings.add(str.substring(i, j));
        }
    }
    return substrings;
}

private String reverseString(String str) {
    return new StringBuilder(str).reverse().toString();
}

private boolean anyStringContains(String sub, List<String> strings) {
    for (String str : strings) {
        if (str.contains(sub) || str.contains(reverseString(sub))) {
            return true;
        }
    }
    return false;
}
