import java.util.List;

public class SubstringFinder {
    public int findLargestSubstring(List<String> strings) {
        int maxLength = 0;

        for (String s : strings) {
            for (String t : strings) {
                if (s.length() > t.length()) {
                    if (containsInverse(s, t)) {
                        maxLength = Math.max(maxLength, s.length());
                    }
                } else {
                    if (containsInverse(t, s)) {
                        maxLength = Math.max(maxLength, t.length());
                    }
                }
            }
        }

        return maxLength;
    }

    private boolean containsInverse(String s, String t) {
        return t.contains(s) || t.contains(new StringBuilder(s).reverse().toString());
    }
}
