public class MazeSolver {
    public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
        int[][] grid = new int[n][n];
        boolean[][] visited = new boolean[n][n];

        for (int[] path : paths) {
            int x1 = path[0];
            int y1 = path[1];
            int x2 = path[2];
            int y2 = path[3];
            grid[x1][y1] = 1;
            grid[x2][y2] = 1;
        }

        int startX = start[0];
        int startY = start[1];
        int endX = end[0];
        int endY = end[1];

        if (dfs(grid, visited, startX, startY, endX, endY)) {
            return "can be travelled";
        } else {
            return "cannot be travelled";
        }
    }

    private static boolean dfs(int[][] grid, boolean[][] visited, int x, int y, int endX, int endY) {
        if (x == endX && y == endY) {
            return true;
        }

        if (x < 0 || x >= grid.length || y < 0 || y >= grid[0].length || grid[x][y] == 0 || visited[x][y]) {
            return false;
        }

        visited[x][y] = true;

        if (dfs(grid, visited, x + 1, y, endX, endY) ||
            dfs(grid, visited, x - 1, y, endX, endY) ||
            dfs(grid, visited, x, y + 1, endX, endY) ||
            dfs(grid, visited, x, y - 1, endX, endY)) {
            return true;
        }

        visited[x][y] = false;
        return false;
    }

    public static void main(String[] args) {
        int n = 4;
        int[] start = {0, 0};
        int[] end = {3, 3};
        int[][] paths = {{0, 0, 0, 1}, {0, 1, 1, 1}, {1, 1, 2, 1}, {2, 1, 2, 2}, {2, 2, 3, 2}, {3, 2, 3, 3}};

        System.out.println(canTravelMaze(n, start, end, paths)); // Output: "can be travelled"
    }
}
