private static boolean dfs(int current, int destination, int[][] paths, boolean[] visited) {
    if (current == destination) {
        return true;
    }
    if (visited[current]) {
        return false;
    }
    visited[current] = true;

    for (int i = 0; i < paths.length; i++) {
        if (paths[i][0] == current) {
            if (dfs(paths[i][1], destination, paths, visited)) {
                return true;
            }
        } else if (paths[i][1] == current) {
            if (dfs(paths[i][0], destination, paths, visited)) {
                return true;
            }
        }
    }

    return false;
}
