private static boolean dfs(int n, int x, int y, int endX, int endY, int[][] paths, boolean[][] visited) {
    if (x < 0 || x >= n || y < 0 || y >= n || visited[x][y]) {
        return false;
    }
    visited[x][y] = true;
    if (x == endX && y == endY) {
        return true;
    }
    if (x > 0 && paths[x - 1][y] == 1 && dfs(n, x - 1, y, endX, endY, paths, visited)) {
        return true;
    }
    if (x < n - 1 && paths[x + 1][y] == 1 && dfs(n, x + 1, y, endX, endY, paths, visited)) {
        return true;
    }
    if (y > 0 && paths[x][y - 1] == 1 && dfs(n, x, y - 1, endX, endY, paths, visited)) {
        return true;
    }
    if (y < n - 1 && paths[x][y + 1] == 1 && dfs(n, x, y + 1, endX, endY, paths, visited)) {
        return true;
    }
    return false;
}
