public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Create a graph to represent the n-interesting space
    Map<String, Set<String>> graph = new HashMap<>();

    // Build the graph using the given paths
    for (int[] path : paths) {
        String from = path[0] + "," + path[1];
        String to = path[2] + "," + path[3];
        graph.computeIfAbsent(from, k -> new HashSet<>()).add(to);
        graph.computeIfAbsent(to, k -> new HashSet<>()).add(from);
    }

    // Helper method to perform DFS
    boolean[] visited = new boolean[n * n];
    public boolean dfs(String current, String end, Set<String> visited) {
        if (current.equals(end)) {
            return true;
        }
        visited.add(current);
        for (String neighbor : graph.getOrDefault(current, new HashSet<>())) {
            if (!visited.contains(neighbor) && dfs(neighbor, end, visited)) {
                return true;
            }
        }
        return false;
    }

    // Convert start and end coordinates to string format
    String startStr = start[0] + "," + start[1];
    String endStr = end[0] + "," + end[1];

    // Perform DFS from start to end
    if (dfs(startStr, endStr, visited)) {
        return "can be travelled";
    } else {
        return "cannot be travelled";
    }
}

