import java.util.HashSet;
import java.util.Set;

public class ApproximateValueCalculator {

    /**
     * Calculates the approximate value of two words.
     *
     * @param word1 The first word.
     * @param word2 The second word.
     * @return The approximate value as a reduced fraction.
     */
    public static String appx(String word1, String word2) {
        Set<Character> commonLetters = new HashSet<>();
        for (char c : word1.toCharArray()) {
            if (word2.indexOf(c) != -1) {
                commonLetters.add(c);
            }
        }

        int numerator = commonLetters.size();
        int denominator = word1.length() + word2.length() - numerator;

        return "appx(" + word1 + ", " + word2 + ") = " + simplify(numerator, denominator);
    }

    /**
     * Simplifies a fraction by finding the greatest common divisor (GCD) and dividing the numerator and denominator.
     *
     * @param numerator   The numerator of the fraction.
     * @param denominator The denominator of the fraction.
     * @return The simplified fraction as a string.
     */
    private static String simplify(int numerator, int denominator) {
        int gcd = gcd(numerator, denominator);
        return numerator / gcd + "/" + denominator / gcd;
    }

    /**
     * Calculates the greatest common divisor (GCD) of two integers using the Euclidean algorithm.
     *
     * @param a The first integer.
     * @param b The second integer.
     * @return The greatest common divisor of a and b.
     */
    private static int gcd(int a, int b) {
        while (b != 0) {
            int temp = b;
            b = a % b;
            a = temp;
        }
        return a;
    }

    public static void main(String[] args) {
        System.out.println(appx("CAR", "CART")); // appx(CAR, CART) = 6/7
        System.out.println(appx("TURKEY", "CHICKEN")); // appx(TURKEY, CHICKEN) = 4/13
        System.out.println(appx("MONEY", "POVERTY")); // appx(MONEY, POVERTY) = 1/3
        System.out.println(appx("ROUGH", "PESKY")); // appx(ROUGH, PESKY) = 0
        System.out.println(appx("A", "A")); // appx(A, A) = 1
    }
}
