import java.util.*;

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Create an adjacency list to represent the tree
    List<List<Integer>> tree = new ArrayList<>();
    for (int i = 0; i < n; i++) {
        tree.add(new ArrayList<>());
    }
    for (int[] edge : edges) {
        tree.get(edge[0]).add(edge[1]);
        tree.get(edge[1]).add(edge[0]);
    }

    // Helper function to perform depth-first search
    return 2 * dfs(0, -1, tree, hasApple);
}

private int dfs(int node, int parent, List<List<Integer>> tree, boolean[] hasApple) {
    int totalTime = 0;

    // Traverse all children of the current node
    for (int child : tree.get(node)) {
        if (child != parent) {
            int timeForChild = dfs(child, node, tree, hasApple);
            // Add the time spent on the child if it contains an apple
            if (timeForChild > 0 || hasApple[child]) {
                totalTime += timeForChild + 2;
            }
        }
    }

    return totalTime;
}
