public int minTime(int n, int[][] edges, boolean[] hasApple) {
    Map<Integer, List<Integer>> graph = new HashMap<>();
    for (int[] edge : edges) {
        int u = edge[0], v = edge[1];
        graph.computeIfAbsent(u, k -> new ArrayList<>()).add(v);
        graph.computeIfAbsent(v, k -> new ArrayList<>()).add(u);
    }

    Map<Integer, Integer> memo = new HashMap<>();
    return Math.max(0, dfs(0, -1, graph, hasApple, memo) * 2);
}

private int dfs(int node, int parent, Map<Integer, List<Integer>> graph, boolean[] hasApple, Map<Integer, Integer> memo) {
    if (memo.containsKey(node)) return memo.get(node);
    if (!graph.containsKey(node) || (graph.get(node).size() == 1 && graph.get(node).get(0) == parent)) {
        memo.put(node, hasApple[node] ? 1 : 0);
        return memo.get(node);
    }

    int time = 0;
    for (int neighbor : graph.get(node)) {
        if (neighbor == parent) continue;
        time += dfs(neighbor, node, graph, hasApple, memo);
    }

    memo.put(node, hasApple[node] ? (time > 0 ? time + 2 : 1) : time);
    return memo.get(node);
}
