private int dfs(int node, int parent, List<Integer>[] adjList, boolean[] hasApple) {
    int time = 0;

    // Iterate through each neighbor of the current node
    for (int neighbor : adjList[node]) {
        if (neighbor == parent) continue; // Skip the parent to avoid cycles
        time += dfs(neighbor, node, adjList, hasApple);
    }

    // If the current node has an apple or its children have apples, add 1 to the time
    if (hasApple[node] || time > 0) {
        time += 1;
    }

    return time;
