import java.util.*;

public class Solution {
    public int minTime(int n, int[][] edges, boolean[] hasApple) {
        // Create adjacency list for the tree
        List<List<Integer>> tree = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            tree.add(new ArrayList<>());
        }
        for (int[] edge : edges) {
            tree.get(edge[0]).add(edge[1]);
            tree.get(edge[1]).add(edge[0]);
        }

        // Use DFS to calculate the minimum time
        boolean[] visited = new boolean[n];
        return dfs(0, visited, tree, hasApple, 0);
    }

    private int dfs(int node, boolean[] visited, List<List<Integer>> tree, boolean[] hasApple, int time) {
        visited[node] = true;
        time += 2; // Each visit takes 2 units of time (one to visit and one to return)

        for (int neighbor : tree.get(node)) {
            if (visited[neighbor]) continue;
            int childTime = dfs(neighbor, visited, tree, hasApple, 0);
            if (childTime > 0 || hasApple[neighbor]) {
                time += childTime;
            }
        }

        if (node == 0) {
            return Math.max(0, time - 2); // Subtract the initial visit time for node 0
        }

        return time;
    }
}
