public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n == 1) {
        return false;
    }

    double sum = 0;
    for (int num : nums) {
        sum += num;
    }
    double target = sum / n;

    Set<Double>[] posSums = new Set[n + 1];
    Set<Double>[] negSums = new Set[n + 1];

    for (int i = 0; i < n + 1; i++) {
        posSums[i] = new HashSet<>();
        negSums[i] = new HashSet<>();
    }

    posSums[0].add(0.0);
    negSums[0].add(0.0);

    for (int i = 0; i < n; i++) {
        for (int k = n - i - 1; k > 0; k--) {
            for (double sumK : posSums[k]) {
                posSums[k + 1].add(sumK + nums[i]);
            }
        }
        for (int k = 0; k < i + 1; k++) {
            for (double sumK : negSums[k]) {
                negSums[k + 1].add(sumK - nums[i]);
            }
        }
    }

    for (int i = 1; i < n + 1; i++) {
        if (posSums[i].isEmpty() || negSums[i].isEmpty()) {
            continue;
        }

        for (double posSum : posSums[i]) {
            double negSum = target * (i + n - i - 1) - posSum;
            if (negSums[n - i].contains(negSum) && posSum != negSum) {
                return true;
            }
        }
    }

    return false;
}
