    for (int i = 0; i <= n; i++) {
        dp[i][0] = true;
    }
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= n / 2; j++) {
            if (j >= nums[i - 1]) {
                dp[i][j] = dp[i - 1][j] || dp[i - 1][j - nums[i - 1]];
            } else {
                dp[i][j] = dp[i - 1][j];
            }
        }
    }
    for (int j = 1; j <= n / 2; j++) {
        if (dp[n][j] && (n - j) * sum / n == j * sum / (n - j)) {
            return true;
        }
    }
    return false;
