    int insertions = 0;

    for (int i = 0; i < s.length(); i++) {
        if (s.charAt(i) == '(') {
            balance++;
        } else {
            if (balance == 0) {
                insertions++; // Missing '('
            }
            balance--;
        }

        if (balance < 0) {
            insertions++; // Missing ')'
            balance = 0;
        }
    }

    return insertions + balance * 2; // Remaining '(' need pairs of ')'
}
