public int findMinFibonacciNumbers(int k) {
    List<Integer> fibNumbers = new ArrayList<>();
    fibNumbers.add(1);
    fibNumbers.add(1);

    // Generate Fibonacci numbers less than or equal to k
    while (true) {
        int nextFib = fibNumbers.get(fibNumbers.size() - 1) + fibNumbers.get(fibNumbers.size() - 2);
        if (nextFib > k) {
            break;
        }
        fibNumbers.add(nextFib);
    }

    int count = 0;
    // Use the largest Fibonacci numbers first to minimize the count
    for (int i = fibNumbers.size() - 1; i >= 0; i--) {
        while (fibNumbers.get(i) <= k) {
            k -= fibNumbers.get(i);
            count++;
        }
    }
    return count;
}
