public int maxUniqueSplit(String s) {
    Set<String> uniqueSubstrings = new HashSet<>();
    return maxUniqueSplitHelper(s, 0, uniqueSubstrings);
}

private int maxUniqueSplitHelper(String s, int start, Set<String> uniqueSubstrings) {
    if (start == s.length()) {
        return uniqueSubstrings.size();
    }

    int maxSplit = 0;
    for (int end = start + 1; end <= s.length(); end++) {
        String substring = s.substring(start, end);
        if (uniqueSubstrings.add(substring)) {
            maxSplit = Math.max(maxSplit, maxUniqueSplitHelper(s, end, uniqueSubstrings));
            uniqueSubstrings.remove(substring); // Backtrack
        }
    }

    return maxSplit;
}
```

