public String getSmallestString(int n, int k) {
    char[] result = new char[n];
    for (int i = 0; i < n; i++) {
        result[i] = 'a';
        k--;
    }
    while (k > 0) {
        for (int i = n - 1; i >= 0; i--) {
            if (k >= 25) {
                result[i] = (char) (result[i] + 25);
                k -= 25;
            } else {
                result[i] = (char) (result[i] + k);
                k = 0;
                break;
            }
        }
    }
    return new String(result);
}

