            if (i >= low) result.add(i);
            queue.add(i);
        }

        while (!queue.isEmpty()) {
            int number = queue.poll();
            int lastDigit = number % 10;

            if (lastDigit == 0) {
                if (number * 10 <= high) {
                    int nextNumber = number * 10;
                    result.add(nextNumber);
                    queue.add(nextNumber);
                }
            } else if (lastDigit == 9) {
                if (number * 10 + 8 <= high) {
                    int nextNumber = number * 10 + 8;
                    result.add(nextNumber);
                    queue.add(nextNumber);
                }
            } else {
                int nextNumber1 = number * 10 + (lastDigit - 1);
                int nextNumber2 = number * 10 + (lastDigit + 1);
                if (nextNumber1 <= high) {
                    result.add(nextNumber1);
                    queue.add(nextNumber1);
                }
                if (nextNumber2 <= high) {
                    result.add(nextNumber2);
                    queue.add(nextNumber2);
                }
            }
        }

        return result;
