public static int countDigitOne(int n) {
    if (n < 0) {
        return 0;
    }

    int count = 0;
    int factor = 1;
    int low = 0, cur = 0, high = 0;

    while (n / factor != 0) {
        low = n - n / factor * factor;
        cur = (n / factor) % 10;
        high = n / (factor * 10);

        if (cur == 0) {
            count += high * factor;
        } else if (cur == 1) {
            count += high * factor + low + 1;
        } else {
            count += (high + 1) * factor;
        }

        factor *= 10;
    }

    return count;
}

