public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return 0;
    }

    int rows = mat.length;
    int cols = mat[0].length;
    int maxLength = 0;

    int[][] horizontal = new int[rows][cols];
    int[][] vertical = new int[rows][cols];
    int[][] diagonal = new int[rows][cols];
    int[][] antiDiagonal = new int[rows][cols];

    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            if (mat[i][j] == 1) {
                horizontal[i][j] = (j > 0 ? horizontal[i][j - 1] : 0) + 1;
                vertical[i][j] = (i > 0 ? vertical[i - 1][j] : 0) + 1;
                diagonal[i][j] = (i > 0 && j > 0 ? diagonal[i - 1][j - 1] : 0) + 1;
                antiDiagonal[i][j] = (i > 0 && j < cols - 1 ? antiDiagonal[i - 1][j + 1] : 0) + 1;

                maxLength = Math.max(maxLength, horizontal[i][j]);
                maxLength = Math.max(maxLength, vertical[i][j]);
                maxLength = Math.max(maxLength, diagonal[i][j]);
                maxLength = Math.max(maxLength, antiDiagonal[i][j]);
            }
        }
    }

    return maxLength;
}
