public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return 0;
    }

    int m = mat.length;
    int n = mat[0].length;
    int maxLength = 0;

    // Arrays to store the count of consecutive 1s for each direction
    int[] horizontal = new int[n];
    int[] vertical = new int[m];
    int[] diagonal = new int[n];
    int[] antiDiagonal = new int[n];

    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                // Update counts for each direction
                horizontal[j] = (j > 0 ? horizontal[j - 1] : 0) + 1;
                vertical[i] = (i > 0 ? vertical[i - 1] : 0) + 1;
                diagonal[j] = (i > 0 && j > 0 ? diagonal[j - 1] : 0) + 1;
                antiDiagonal[j] = (i > 0 && j < n - 1 ? antiDiagonal[j + 1] : 0) + 1;

                // Update the maximum length
                maxLength = Math.max(maxLength, horizontal[j]);
                maxLength = Math.max(maxLength, vertical[i]);
                maxLength = Math.max(maxLength, diagonal[j]);
                maxLength = Math.max(maxLength, antiDiagonal[j]);
            } else {
                // Reset counts if the current cell is 0
                horizontal[j] = 0;
                vertical[i] = 0;
                diagonal[j] = 0;
                antiDiagonal[j] = 0;
            }
        }
    }

    return maxLength;
}
