public static int squarePermutations(int[] A) {
    if (A == null || A.length == 0) {
        return 0;
    }

    int n = A.length;
    boolean[] visited = new boolean[n];
    int count = 0;

    // Helper function to check if a number is a perfect square
    boolean isPerfectSquare(int num) {
        int sqrt = (int) Math.sqrt(num);
        return sqrt * sqrt == num;
    }

    // Helper function to perform DFS
    void dfs(List<Integer> current, int[] A, boolean[] visited, int start) {
        if (current.size() == A.length) {
            count++;
            return;
        }

        for (int next = start; next < A.length; next++) {
            if (!visited[next] && isPerfectSquare(current.get(current.size() - 1) + A[next])) {
                visited[next] = true;
                current.add(A[next]);
                dfs(current, A, visited, 0);
                current.remove(current.size() - 1);
                visited[next] = false;
            }
        }
    }

    // Start DFS from each element
    for (int i = 0; i < n; i++) {
        List<Integer> current = List.of(A[i]);
        visited[i] = true;
        dfs(current, A, visited, 0);
        visited[i] = false;
    }

    return count;
}
