    if (n == 0) return 1; // An empty array is considered a valid permutation
    return countPermutations(A, 0, new int[n], new boolean[n]);
}

private static int countPermutations(int[] A, int index, int[] result, boolean[] used) {
    if (index == A.length) return 1;

    int count = 0;
    for (int i = 0; i < A.length; i++) {
        if (!used[i] && isPerfectSquare(A[index] + A[i])) {
            result[index] = A[i];
            used[i] = true;
            count += countPermutations(A, index + 1, result, used);
            used[i] = false;
        }
    }

    return count;
}

private static boolean isPerfectSquare(int num) {
    int sqrt = (int) Math.sqrt(num);
    return sqrt * sqrt == num;
}
