public static int squarePermutations(int[] A) {
    List<List<Integer>> result = new ArrayList<>();
    boolean[] used = new boolean[A.length];
    Arrays.sort(A);
    backtrack(result, new ArrayList<>(), A, used);
    return result.size();
}

private static void backtrack(List<List<Integer>> result, List<Integer> temp, int[] A, boolean[] used) {
    if (temp.size() == A.length) {
        result.add(new ArrayList<>(temp));
        return;
    }

    for (int i = 0; i < A.length; i++) {
        if (used[i] || (i > 0 && A[i] == A[i - 1] && !used[i - 1])) {
            continue;
        }
        if (temp.isEmpty() || isPerfectSquare(temp.get(temp.size() - 1), A[i])) {
            temp.add(A[i]);
            used[i] = true;
            backtrack(result, temp, A, used);
            used[i] = false;
            temp.remove(temp.size() - 1);
        }
    }
