private static int helper(int[] A, int index, int count, boolean[] used) {
    if (index == A.length) {
        return 1;
    }

    int result = 0;
    for (int i = 0; i < A.length; i++) {
        if (!used[i] && isPerfectSquare(A[index] + A[i]) && (index == 0 || isPerfectSquare(A[index - 1] + A[i]))) {
            used[i] = true;
            result += helper(A, index + 1, count + 1, used);
            used[i] = false;
        }
    }

    return result;
}

private static boolean isPerfectSquare(int num) {
    int sqrt = (int) Math.sqrt(num);
    return sqrt * sqrt == num;
