public static int[] diagonalOrder(int[][] mat) {
    if (mat.length == 0 || mat[0].length == 0) {
        return new int[]{};
    }

    int rows = mat.length;
    int cols = mat[0].length;
    int[] result = new int[rows * cols];
    int r = 0, c = 0, d = 1; // d is the direction, 1 for up-right, -1 for down-left

    for (int i = 0; i < result.length; i++) {
        result[i] = mat[r][c];
        r -= d;
        c += d;

        if (r < 0 || r >= rows || c < 0 || c >= cols) {
            if (d == 1) {
                r = c < 0 ? 0 : r;
                c = c < 0 ? -1 : c;
                d = -1;
            } else {
                c = r < 0 ? 0 : c;
                r = r < 0 ? -1 : r;
                d = 1;
            }
        }
    }

    return result;
}
