public class Solution {
    public static int[] diagonalOrder(int[][] mat) {
        if (mat == null || mat.length == 0 || mat[0].length == 0) {
            return new int[0];
        }

        int rows = mat.length;
        int cols = mat[0].length;
        int[] result = new int[rows * cols];
        int index = 0;

        for (int k = 0; k < rows + cols - 1; k++) {
            if (k % 2 == 0) {
                for (int i = Math.min(k, rows - 1); i >= Math.max(0, k - cols + 1); i--) {
                    result[index++] = mat[i][k - i];
                }
            } else {
                for (int i = Math.max(0, k - cols + 1); i <= Math.min(k, rows - 1); i++) {
                    result[index++] = mat[i][k - i];
                }
            }
        }

        return result;
    }

    public static void main(String[] args) {
        int[][] mat = {
            {1, 2, 3},
            {4, 5, 6},
            {7, 8, 9}
        };
        int[] result = diagonalOrder(mat);
        for (int num : result) {
            System.out.print(num + " ");
        }
    }
}
