public static int findSmallestInteger(int n) {
    char[] digits = Integer.toString(n).toCharArray();
    int len = digits.length;

    // Start from the rightmost character and find the first digit that is smaller than the digit next to it
    int i;
    for (i = len - 2; i >= 0; i--) {
        if (digits[i] < digits[i + 1]) {
            break;
        }
    }

    // If no such digit is found, it means the digits are in descending order
    if (i == -1) {
        return -1;
    }

    // Find the smallest digit on the right side of (i) which is greater than digits[i]
    int j;
    for (j = len - 1; j > i; j--) {
        if (digits[j] > digits[i]) {
            break;
        }
    }

    // Swap the found digits
    char temp = digits[i];
    digits[i] = digits[j];
    digits[j] = temp;

    // Sort the digits after the (i)th position in ascending order
    Arrays.sort(digits, i + 1, len);

    // Convert the character array back to an integer
    try {
        return Integer.parseInt(new String(digits));
    } catch (NumberFormatException e) {
        return -1;
    }
}
