public static List<String> centerSymmetricNumbers(int n) {
    if (n <= 0) {
        return Collections.emptyList();
    }

    List<String> result = new ArrayList<>();
    centerSymmetricNumbersHelper(result, n, new char[n], 0, n - 1);
    return result;
}

private static void centerSymmetricNumbersHelper(List<String> result, int n, char[] current, int left, int right) {
    if (left > right) {
        result.add(String.valueOf(current));
        return;
    }

    char[] symmetries = {'0', '1', '6', '8', '9'};
    for (char sym : symmetries) {
        if (n == 1 && sym == '0' && left == right) {
            continue; // Skip '0' when n is 1 to avoid leading zeros
        }
        current[left] = sym;
        current[right] = getSymmetric(sym);
        if (left != right || sym != getSymmetric(sym)) {
            centerSymmetricNumbersHelper(result, n, current, left + 1, right - 1);
        }
    }
}

private static char getSymmetric(char c) {
    switch (c) {
        case '6': return '9';
        case '9': return '6';
        default: return c;
    }
}
