import java.util.ArrayList;
import java.util.List;

public class Solution {
    public static List<String> centerSymmetricNumbers(int n) {
        List<String> result = new ArrayList<>();
        char[] pairs = new char[]{'0', '1', '6', '8', '9'};
        helper(result, new char[n], pairs, 0, n - 1);
        return result;
    }

    private static void helper(List<String> result, char[] chars, char[] pairs, int left, int right) {
        if (left > right) {
            result.add(new String(chars));
            return;
        }

        if (left == right) {
            for (int i = 0; i < pairs.length; i++) {
                if (pairs[i] == '0' && chars.length != 1) continue;
                chars[left] = pairs[i];
                result.add(new String(chars));
            }
        } else {
            for (int i = 0; i < pairs.length / 2; i++) {
                chars[left] = pairs[i];
                chars[right] = pairs[pairs.length - 1 - i];
                helper(result, chars, pairs, left + 1, right - 1);
            }
        }
    }

    public static void main(String[] args) {
        System.out.println(centerSymmetricNumbers(2)); // Output: [11, 69, 88, 96]
        System.out.println(centerSymmetricNumbers(1)); // Output: [0, 1, 8]
    }
}
