import java.util.ArrayList;
import java.util.List;

public class CenterSymmetricNumbers {

    public static List<String> centerSymmetricNumbers(int n) {
        if (n == 0) return new ArrayList<>();
        if (n == 1) return new ArrayList<String>() {{
            add("0");
            add("1");
            add("8");
        }};

        List<String> symNumbers = new ArrayList<>();
        if (n % 2 == 0) {
            helper("", n / 2, symNumbers);
        } else {
            helper("0", n / 2, symNumbers);
            helper("1", n / 2, symNumbers);
            helper("8", n / 2, symNumbers);
        }

        return symNumbers;
    }

    private static void helper(String prefix, int length, List<String> symNumbers) {
        if (prefix.length() == length) {
            symNumbers.add(prefix + reverseAndReplace(prefix));
            return;
        }

        if (prefix.length() == length - 1) {
            helper(prefix + "0", length, symNumbers);
        }

        helper(prefix + "1", length, symNumbers);
        helper(prefix + "6", length, symNumbers);
        helper(prefix + "8", length, symNumbers);
        helper(prefix + "9", length, symNumbers);
    }

    private static String reverseAndReplace(String s) {
        char[] chars = s.toCharArray();
        for (int i = 0; i < chars.length; i++) {
            if (chars[i] == '6') chars[i] = '9';
            else if (chars[i] == '9') chars[i] = '6';
        }

        return new StringBuilder(mirror(s)).reverse().toString();
    }

    private static String mirror(String s) {
        char[] chars = s.toCharArray();
        for (int i = 0; i < chars.length; i++) {
            if (chars[i] == '1') chars[i] = '1';
            else if (chars[i] == '6') chars[i] = '9';
            else if (chars[i] == '8') chars[i] = '8';
            else if (chars[i] == '9') chars[i] = '6';
        }

        return new String(chars);
    }

    // Test cases
    public static void main(String[] args) {
        System.out.println(centerSymmetricNumbers(2)); // Output: ["11","69","88","96"]
        System.out.println(centerSymmetricNumbers(1)); // Output: ["0","1","8"]
    }
}
