import java.util.ArrayList;
import java.util.List;

public class LexicographicalOrder {
    public static List<Integer> lexicalOrder(int n) {
        List<Integer> result = new ArrayList<>();
        for (int i = 1; i <= 9; i++) {
            if (i <= n) {
                result.add(i);
                addNumbers(result, i * 10, n);
            }
        }
        return result;
    }

    private static void addNumbers(List<Integer> result, int start, int n) {
        for (int i = 0; i <= 9; i++) {
            int num = start + i;
            if (num > n) {
                return;
            }
            result.add(num);
            addNumbers(result, num * 10, n);
        }
    }

    public static void main(String[] args) {
        List<Integer> result = lexicalOrder(13);
        System.out.println(result); // Output: [1,10,11,12,13,2,3,4,5,6,7,8,9]
    }
}
```

